const items = $input.all();

// Date in dd/mm/yyyy format
const today = new Date();
const day = String(today.getDate()).padStart(2, '0');
const month = String(today.getMonth() + 1).padStart(2, '0');
const year = today.getFullYear();
const orderDate = `${day}/${month}/${year}`;

// Get opportunity ID from webhook — not from product properties
const opportunityId = $('Webhook').first().json.body.opportunity_id;
const orderNumber = `ORD-${opportunityId}`;

// SAP Customer Number — temporary hardcode until account fetch is added
// TODO: fetch from GHL Account linked to this opportunity
const customerNumber = 'YOUR_SAP_CUSTOMER_NUMBER'; // Replace with your SAP debtor account number

// Debug — log all items to see what fields exist
items.forEach((item, i) => {
  console.log(`Item ${i}:`, JSON.stringify(item.json.record.properties));
});

// Build XML lines — skip lines missing SAP code or quantity
const linesXml = items
  .filter(item =>
    item.json.record.properties.sap_code &&
    item.json.record.properties.quantity
  )
  .map((item, index) => `
      <SalesLine>
         <LineNumber>${index + 1}</LineNumber>
         <ProductCode>${String(item.json.record.properties.sap_code).padStart(18, '0')}</ProductCode>
         <OrderQty>${item.json.record.properties.quantity}</OrderQty>
      </SalesLine>`
  ).join('');

// Build complete XML string
const xml = `<?xml version="1.0" encoding="UTF-8"?>
<ns0:SalesOrder xmlns:ns0="http://united-drug.com/EOS/SalesOrder/Inbound/Generic_SalesOrder">
   <OrderNumber>${orderNumber}</OrderNumber>
   <OrderDate>${orderDate}</OrderDate>
   <Customer>${customerNumber}</Customer>
   <OrderRef/>
   <Company>YOUR_SAP_COMPANY_CODE</Company>
   <PartnerId>YOUR_SAP_PARTNER_ID</PartnerId>
   <Channel>20</Channel>
   <SalesLines>${linesXml}
   </SalesLines>
</ns0:SalesOrder>`;

const fileName = `Distinct_Sales_${year}${month}${day}.xml`;

return [{ json: { xml, fileName } }];
